def profile():
    from flask import render_template_string, request, session
    username = request.args.get('name', session.get('username', 'Guest'))
    comment = request.args.get('comment', 'No comment')

    template = '''
        <h1>User Profile</h1>
        <p>Welcome, {{ username }}!</p>
        <p>Your comment: {{ comment }}</p>
        {% if is_admin %}
        <p style="color:red;">Password Hint: {{ password_hint }}</p>
        {% endif %}
    '''

    context = {
        'username': username,
        'comment': comment,
        'is_admin': username == 'admin',
        'password_hint': ADMIN_PASSWORD if username == 'admin' else ''
    }

    return render_template_string(template, **context)
